import java.util.concurrent.*;public class ThreadPoolRunner{public static void main(String[]x)throws Exception{ExecutorService e=Executors.newFixedThreadPool(3);for(int i=1;i<=10;i++){final int id=i;e.submit(()->{try{Thread.sleep(100);}catch(InterruptedException ex){Thread.currentThread().interrupt();}System.out.println("Task "+id+" on "+Thread.currentThread().getName());});}e.shutdown();e.awaitTermination(5,TimeUnit.SECONDS);}}
